def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    The text is split into lines. Each line is split at its first "=" into a
    name and a value, and whitespace around both is stripped. Because only the
    first "=" splits the line, a value may itself contain "=".

    The key is matched exactly (case-sensitive) against the stripped name.
    Lines without "=" and blank lines are ignored. No comment syntax is
    recognised. If the key appears more than once, the first occurrence wins.

    Returns "" when the key is absent. A key that is present with an empty
    value also gives "".
    """
    for line in text.splitlines():
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    text = "a=1\nb=2\nc=3"
    assert config_value(text, "a") == "1"
    assert config_value(text, "b") == "2"
    assert config_value(text, "c") == "3"


def test_missing_key_returns_empty() -> None:
    assert config_value("a=1\nb=2", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_stripped_around_name_and_value() -> None:
    assert config_value("  name  =  some value  \n", "name") == "some value"


def test_lookup_key_is_not_stripped_implicitly() -> None:
    # The key must match the stripped name exactly.
    assert config_value("name=x", "name ") == ""


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?a=b&c=d", "url") == "http://x/?a=b&c=d"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_case_sensitive() -> None:
    assert config_value("Key=1", "key") == ""
    assert config_value("Key=1", "Key") == "1"


def test_first_duplicate_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_lines_without_equals_and_blank_lines_ignored() -> None:
    text = "\njunk line\n\na=1\n   \n"
    assert config_value(text, "a") == "1"
    assert config_value(text, "junk line") == ""


def test_key_must_match_whole_name() -> None:
    text = "abc=1\nab=2"
    assert config_value(text, "ab") == "2"
    assert config_value(text, "a") == ""


def test_name_is_not_matched_by_value() -> None:
    assert config_value("a=b\nb=c", "b") == "c"


def test_windows_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


def test_no_comment_syntax() -> None:
    assert config_value("#a=1", "#a") == "1"
    assert config_value("#a=1", "a") == ""


def test_empty_key_matches_empty_name() -> None:
    assert config_value("=v\na=1", "") == "v"
    assert config_value("a=1", "") == ""

